#nullable disable warnings
using LoonieRoo.Sim;
using static LoonieRoo.Sim.Tests.Vitest;
namespace LoonieRoo.Sim.Tests.Ported;

public partial class RelationshipsTest
{

    public static SimState setup(List<string> map)
    {
        var state = ScenarioMod.loadScenario(new Scenario { seed = 2, map = map });
        foreach (var s in Js.Iter(state.survivors))
        {
            s.priorities = new(JobTypes.NO_JOBS) {  };
        }
        return state;
    }

    /// <summary>relationships</summary>
    public class D001_relationships
    {

        [Fact(DisplayName = "relationships > survivors who spend time near each other warm to each other; distant ones don't")]
        public void T002_survivors_who_spend_time_near_each_other_warm_to_each_other_()
        {
            var state = setup(["s.s.........s"]);
            var (a, b, far) = state.survivors;
            for (var i = 0; i < (3 * Relationships.BOND_EVERY); i++)
            {
                Tick.tick(state);
            }
            expect(Relationships.opinion(Js.NN(a), Js.NN(b))).toBe(3 * Relationships.BOND);
            expect(Relationships.opinion(Js.NN(b), Js.NN(a))).toBe(3 * Relationships.BOND);
            expect(Relationships.opinion(Js.NN(a), Js.NN(far))).toBe(0);
        }

        [Fact(DisplayName = "relationships > a friend's death hurts more than a stranger's")]
        public void T003_a_friend_s_death_hurts_more_than_a_stranger_s()
        {
            var state = setup(["s.s.s"]);
            var (dead, friend, stranger) = state.survivors;
            Js.NN(friend).opinions[Js.Idx(Js.NN(dead).id)] = Relationships.FRIEND;
            Needs.killSurvivor(state, Js.NN(dead), "a test");
            expect(Js.NN(friend).thoughts.map((t) => t.kind)).toEqual(Js.Arr(["lostFriend"]));
            expect(Js.NN(stranger).thoughts.map((t) => t.kind)).toEqual(Js.Arr(["sawDeath"]));
            expect(Js.NN(friend).opinions).toEqual(Js.Obj());
        }

        [Fact(DisplayName = "relationships > a breakdown lashes out at the nearest; a rival hits back")]
        public void T004_a_breakdown_lashes_out_at_the_nearest_a_rival_hits_back()
        {
            var state = setup(["s.s....."]);
            var (a, b) = state.survivors;
            Relationships.lashOut(state, Js.NN(a));
            expect(Relationships.opinion(Js.NN(b), Js.NN(a))).toBeLessThan(0);
            expect(Js.NN(a).health).toBe(1000);
            Js.NN(b).opinions[Js.Idx(Js.NN(a).id)] = -60;
            Relationships.lashOut(state, Js.NN(a));
            expect(Js.Arr([Js.NN(a).health, Js.NN(b).health])).toEqual(Js.Arr([1000 - Relationships.FIGHT_DAMAGE, 1000 - Relationships.FIGHT_DAMAGE]));
            expect(Js.NN(state.events.at(-1)).message).toBe($"{Js.Str(Js.NN(a).name)} and {Js.Str(Js.NN(b).name)} came to blows");
        }
    }
}
